            <img src={LOGO_URL} alt="Español con Claudia" className="h-12 md:h-16 w-auto object-contain" />
          </a>

          {/* Desktop Nav */}
          <div className="hidden lg:flex items-center space-x-8">
            <div className="flex space-x-6">
              {NAV_ITEMS.map((item) => (
                <a
                  key={item.label}
                  href={item.href}
                  className="text-white font-medium hover:text-brand-supernova transition-colors relative group text-sm uppercase tracking-wide"
                >
                  {item.label}
                  <span className="absolute -bottom-1 left-0 w-0 h-0.5 bg-brand-supernova transition-all duration-300 group-hover:w-full"></span>
                </a>
              ))}
            </div>

            {/* Social Icons Desktop */}
            <div className="flex items-center space-x-3 ml-6 border-l border-white/20 pl-6">
              <a href="#" className="bg-white/10 p-2 rounded-full hover:bg-brand-supernova hover:text-brand-darkBlue text-white transition-all">
                <Facebook size={18} />
              </a>
              <a href="#" className="bg-white/10 p-2 rounded-full hover:bg-brand-supernova hover:text-brand-darkBlue text-white transition-all">
                <Instagram size={18} />
              </a>
              <a href="#" className="bg-brand-crimson p-2 rounded-full hover:bg-red-600 text-white transition-all shadow-lg animate-pulse">
                <Phone size={18} />
              </a>
