import React, { useState } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import Services from './components/Services';
import Gallery from './components/Gallery';
import Footer from './components/Footer';
import WhatsAppButton from './components/WhatsAppButton';
import AboutPage from './components/AboutPage';
import ContactPage from './components/ContactPage';

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<'home' | 'about' | 'contact'>('home');

  // Handle navigation requests
  const handleNavigate = (page: string, sectionId?: string) => {
    // If going to a different page, update state
    if (page === 'home' || page === 'about' || page === 'contact') {
      setCurrentPage(page as 'home' | 'about' | 'contact');
    }

    // Handle scrolling if on home page
    if (page === 'home' && sectionId) {
      // If we are already on home, scroll immediately
      // If we are changing pages, we need to wait for render
      setTimeout(() => {
        const element = document.getElementById(sectionId);
        if (element) {
          element.scrollIntoView({ behavior: 'smooth' });
        } else if (sectionId === 'home') {
          window.scrollTo({ top: 0, behavior: 'smooth' });
        }
      }, 100);
    } else {
      // Scroll to top for new pages
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  return (
    <div className="font-sans antialiased text-gray-900">
      <Navbar onNavigate={handleNavigate} currentPage={currentPage} />

      <main>
        {currentPage === 'home' ? (
          <>
            <Hero onNavigate={handleNavigate} />
            <Services onNavigate={handleNavigate} />
            <Gallery />
          </>
        ) : currentPage === 'about' ? (
          <AboutPage />
        ) : (
          <ContactPage />
        )}
      </main>

      <Footer />
      <WhatsAppButton />
    </div>
  );
};

